/** 未命中映射时的字母圆标字符：name 优先，providerCode 次之，均为空回「?」。 */
export function providerIconFallbackChar(name?: string, providerCode?: string): string {
  const firstOf = (value?: string): string => (value?.trim().charAt(0) ?? '').toUpperCase()
  return firstOf(name) || firstOf(providerCode) || '?'
}
